from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output

from taf.rfrl.procedures.resources.python.status_check.rmod.ran.ran_rmod_factory import RanRmodFactory
from taf.rfrl.procedures.resources.python.status_check.rmod.oran.oran_rmod_factory import OranRmodFactory


class RmodFactory:
    """
    Creates RAN or ORAN Rmod instances with appropriate link protocol CPRI, eCPRI or OBSAI configuration.
    """

    @staticmethod
    @log_input_and_output
    def create_rmod(rmod_ran_protocol, rmod_link_protocol):
        """
        Creates Rmod instance
        :param rmod_ran_protocol: type of rmod protocol, can be "NOKIA" or "O-RAN"
        :type rmod_ran_protocol: str
        :param rmod_link_protocol: type of rmod link protocol, can be "CPRI", "eCPRI" or "OBSAI"
        :type rmod_link_protocol: str
        :return: CpriRmod, EcpriRmod or ObsaiRmod instance
        :rtype: Rmod
        """
        if rmod_ran_protocol == "NOKIA":
            return RanRmodFactory.create_ran_rmod(rmod_link_protocol)
        elif rmod_ran_protocol == "O-RAN":
            return OranRmodFactory.create_oran_rmod(rmod_link_protocol)
